import torch
import torch.nn as nn

class DeltaRouter(nn.Module):
    def __init__(self, hidden_size: int, num_heads: int = 1):
        super().__init__()
        self.query = nn.Parameter(torch.zeros(num_heads, hidden_size))
        self.null_logit = nn.Parameter(torch.zeros(num_heads))
        self.head_dim = hidden_size // num_heads

    def forward(self, residual, deltas):
        keys = nn.functional.normalize(deltas, dim=-1)
        logits = torch.einsum('hd,lbtd->hlbt', self.query, keys)
        weights = torch.softmax(logits, dim=1)
        return residual + torch.einsum('hlbt,lbtd->btd', weights, deltas)

async function fetchManifest(url, { retries = 3, timeoutMs = 5000 } = {}) {
  for (let attempt = 0; attempt < retries; attempt++) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    try {
      const res = await fetch(url, { signal: controller.signal });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      return await res.json();
    } catch (err) {
      if (attempt === retries - 1) throw err;
    } finally {
      clearTimeout(timer);
    }
  }
}
